fn solve(x: i32) -> i32 {
    // Convert x to string to easily access digits and length
    let s = x.to_string();
    let digit = s.chars().next().unwrap().to_digit(10).unwrap() as i32;
    let k = s.len() as i32;

    // Calculate the score
    // For each digit from 1 to (digit - 1), we typed all 4 lengths: 1+2+3+4 = 10 presses each
    let presses_before_digit = (digit - 1) * 10;
    // For the current digit, we typed lengths 1..=k
    let presses_current_digit = (1..=k).sum::<i32>();

    presses_before_digit + presses_current_digit
}